    for value in reversed(values):
        head = ListNode(value, head)
    return head
def to_list(node):
    out = []
    while node is not None and len(out) < 10_000:
        out.append(node.val)
        node = node.next
    return out
def wrong_removals(max_length):
    """Try every list length up to max_length and every n; describe the first few wrong answers (an empty list means all were right)."""
    wrong = []
    for length in range(1, max_length + 1):
        values = list(range(10, 10 + length))
        for n in range(1, length + 1):
            got = to_list(remove_nth_from_end(build(values), n))
            expected = values[:length - n] + values[length - n + 1:]
            if got != expected:
                wrong.append(f"{values} with n={n}: got {got}, expected {expected}")
    return wrong[:3]

def names_of(head, named):
    """Name each node of the chain by the variable it was created as ("new node" for one the function made itself)."""
    out = []
    while head is not None and len(out) < 20:
        out.append(named.get(id(head), "new node"))
        head = head.next
    return out
